var pi = PhaseManager.get_current_phase_instance()
var n = 0
while pi.has_method("get_pending_stratagem_window") and not pi.get_pending_stratagem_window().is_empty() and n < 6:
	var w = pi.get_pending_stratagem_window()
	pi.execute_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(pi.get_pending_stratagem_window_decider()), "window_id": w.get("window_id", "")})
	n += 1
var d = AIPlayer.request_suggestion()
var types = []
for rr in d.get("_ai_decision_records", []):
	types.append(str(rr.get("decision_type", "")))
if "fight" in types or str(d.get("_ai_description", "")).contains(" with "):
	return "FIGHT_RECORD " + str(d.get("_ai_description", ""))
var r = pi.execute_action(d)
return str(types) + " " + str(d.get("_ai_description", "")) + " -> " + str(r.get("success", false))

var n = 0
for w in tree.root.find_children("*", "AcceptDialog", true, false):
	if w.visible and w.get_script() != null and str(w.get_script().resource_path).ends_with("EpicChallengeDialog.gd"):
		w._on_decline_pressed()
		n += 1
return n

